# 
# ---- SLR Example: Cognitive Rehabilitation and Memory Gain ---------------------
# 
# **Context:**
# 
# Cognitive rehabilitation is a core intervention in clinical neuropsychology.
# Patients recovering from acquired brain injury (e.g. stroke, TBI) undergo
# structured cognitive training programmes aimed at restoring everyday function.
# 
# Here we ask: does the number of completed training hours predict the gain
# in episodic memory performance observed at the end of rehabilitation?
# Memory gain is operationalised as the change score on a standardised
# word-list recall test (post-treatment minus pre-treatment, in raw score points).
# A positive gain means improvement.
# 
# **You will see:**
# 
# 1. How to fit a simple linear regression in R
# 2. How to interpret the intercept and slope in a clinical context
# 3. How to reproduce every number in summary() and anova() manually
# 4. How to run the four standard diagnostic plots
# 
library(psych)
library(ggplot2)

rm(list = ls())

# 
# ---- Data generation -----------------------------------------------------------
# 
n        <- 15   # small rehabilitation cohort — easy to inspect
alpha_T  <- 2.0  # true intercept: expected gain with zero training hours (baseline drift)
beta_T   <- 0.8  # true slope: each extra training hour gains 0.8 recall points on average
sd_error <- 3.0  # individual variability around the true line
mu_x     <- 12   # mean training hours completed across patients
sigma_x  <- 4    # SD of training hours

set.seed(42)
trainingHours <- rnorm(n, mu_x, sigma_x)
memoryGain    <- alpha_T + beta_T * trainingHours + rnorm(n, 0, sd_error)

dataRehab <- data.frame(
  memoryGain    = memoryGain,    # outcome Y  (recall score change, points)
  trainingHours = trainingHours  # predictor X (hours of cognitive training completed)
)

# quick look
str(dataRehab)
head(dataRehab)
psych::describe(dataRehab)

# 
# ---- Visualise the data --------------------------------------------------------
# 
with(dataRehab, plot(trainingHours, memoryGain,
                     xlab = "Cognitive training completed (hours)",
                     ylab = "Memory gain (recall score change)",
                     main = "Rehabilitation dose and memory recovery"))
abline(lm(memoryGain ~ trainingHours, data = dataRehab), col = "steelblue", lwd = 2)

ggplot(dataRehab, aes(x = trainingHours, y = memoryGain)) +
  geom_point(size = 2) +
  geom_smooth(method = "lm", se = TRUE, colour = "steelblue") +
  labs(x = "Cognitive training completed (hours)",
       y = "Memory gain (recall score change)",
       title = "Does rehabilitation dose predict memory recovery?")

# 
# ---- Step 1: Fit the model -----------------------------------------------------
# 
# Fit the simple linear regression
lmRehab <- lm(memoryGain ~ trainingHours, data = dataRehab)
lmRehab

# Inspect the full output
summary(lmRehab)
anova(lmRehab)

# The estimated slope can be compared to the true value beta_T = 0.8 used to generate the data.

# 
# ---- Step 2: Manual slope and intercept ----------------------------------------
# 
means <- apply(dataRehab, 2, mean)
stdvs <- apply(dataRehab, 2, sd)
means
stdvs

# Pearson r
r <- with(dataRehab, cor(memoryGain, trainingHours))
r

# Slope from correlation: beta = r * (SD_y / SD_x)
hat_beta <- unname(r * (stdvs["memoryGain"] / stdvs["trainingHours"]))
hat_beta

# Intercept: alpha = mean_y - beta * mean_x
hat_alpha <- unname(means["memoryGain"] - hat_beta * means["trainingHours"])
hat_alpha

# Compare to lm()
coef(lmRehab)

# 
# ---- Step 3: Sums of squares and R-squared -------------------------------------
# 
fitted_vals   <- hat_alpha + hat_beta * dataRehab$trainingHours
residual_vals <- dataRehab$memoryGain - fitted_vals

SS_Tot <- unname((n - 1) * stdvs["memoryGain"]^2)       # total variability in Y
SS_Reg <- sum((fitted_vals - means["memoryGain"])^2)     # explained by training hours
SS_Res <- sum(residual_vals^2)                           # unexplained (residuals)
SS_Tot
SS_Reg
SS_Res

# check: SS_Tot == SS_Reg + SS_Res
dplyr::near(SS_Tot, SS_Reg + SS_Res)

# Compare to anova()
anova(lmRehab)

# R-squared: proportion of variance in memory gain explained by training dose
R_sq <- SS_Reg / SS_Tot
R_sq

# 
# ---- Step 4: F-statistic and p-value -------------------------------------------
# 
MS_Reg <- SS_Reg / 1          # df_model = 1 (one predictor)
MS_Res <- SS_Res / (n - 2)    # df_residual = n - 2
F_stat <- MS_Reg / MS_Res
MS_Reg
MS_Res
F_stat

# p-value from the F distribution
pf(F_stat, df1 = 1, df2 = n - 2, lower.tail = FALSE)

# 
# ---- Step 5: Diagnostics -------------------------------------------------------
# 
par(mfrow = c(2, 2))
plot(lmRehab)
dev.off()

# Check: normality of residuals (Q-Q plot), linearity (residuals vs fitted),
# homoscedasticity (scale-location), and influential cases (Cook's distance).
